PRAGMA foreign_keys=ON;
CREATE TABLE schema_versions(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE departments(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE positions(id INTEGER PRIMARY KEY, title TEXT NOT NULL UNIQUE, required_skills TEXT NOT NULL DEFAULT '[]');
CREATE TABLE teams(id INTEGER PRIMARY KEY, name TEXT NOT NULL, department_id INTEGER NOT NULL REFERENCES departments(id));
CREATE TABLE employees(id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, phone TEXT DEFAULT '', department_id INTEGER NOT NULL REFERENCES departments(id), position_id INTEGER REFERENCES positions(id), team_id INTEGER REFERENCES teams(id), manager_id INTEGER REFERENCES employees(id), leader_id INTEGER REFERENCES employees(id), employment_type TEXT DEFAULT 'Full time', work_mode TEXT NOT NULL DEFAULT 'Office', joined TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Active', salary_cents INTEGER NOT NULL CHECK(salary_cents>=0), annual_days REAL NOT NULL DEFAULT 21, skills TEXT NOT NULL DEFAULT '[]');
CREATE TABLE roles(id TEXT PRIMARY KEY, label TEXT NOT NULL);
CREATE TABLE permissions(id TEXT PRIMARY KEY);
CREATE TABLE role_permissions(role_id TEXT REFERENCES roles(id), permission_id TEXT REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE users(id INTEGER PRIMARY KEY, employee_id INTEGER UNIQUE NOT NULL REFERENCES employees(id), email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL REFERENCES roles(id));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE attendance(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), day TEXT NOT NULL, check_in TEXT, check_out TEXT, minutes INTEGER DEFAULT 0, late_minutes INTEGER DEFAULT 0, early_minutes INTEGER DEFAULT 0, overtime_minutes INTEGER DEFAULT 0, work_mode TEXT NOT NULL DEFAULT 'Office', exception TEXT DEFAULT '', UNIQUE(employee_id,day));
CREATE TABLE leave_types(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, deduct_balance INTEGER NOT NULL DEFAULT 0, payroll_factor REAL NOT NULL DEFAULT 0, unit TEXT NOT NULL DEFAULT 'days');
CREATE TABLE leave_requests(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), type_id INTEGER NOT NULL REFERENCES leave_types(id), start TEXT NOT NULL, end TEXT NOT NULL, units REAL NOT NULL CHECK(units>0), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', approver_id INTEGER REFERENCES employees(id), decision_reason TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leave_balances(employee_id INTEGER REFERENCES employees(id), year INTEGER NOT NULL, entitlement REAL NOT NULL, used REAL NOT NULL DEFAULT 0 CHECK(used>=0), PRIMARY KEY(employee_id,year));
CREATE TABLE approval_history(id INTEGER PRIMARY KEY, request_id INTEGER REFERENCES leave_requests(id), actor_id INTEGER REFERENCES users(id), decision TEXT NOT NULL, reason TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payroll(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), month TEXT NOT NULL, basic_cents INTEGER NOT NULL, additions_cents INTEGER NOT NULL, deductions_cents INTEGER NOT NULL, gross_cents INTEGER NOT NULL, net_cents INTEGER NOT NULL, breakdown TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Draft', created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(employee_id,month));
CREATE TABLE salary_components(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), month TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('Addition','Deduction')), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), reason TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 1);
CREATE TABLE performance_periods(id INTEGER PRIMARY KEY, name TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL);
CREATE TABLE kpis(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), period_id INTEGER REFERENCES performance_periods(id), title TEXT NOT NULL, target REAL NOT NULL CHECK(target>0), actual REAL NOT NULL DEFAULT 0, weight REAL NOT NULL CHECK(weight>0), direction TEXT NOT NULL DEFAULT 'higher', status TEXT NOT NULL DEFAULT 'Proposed');
CREATE TABLE reports(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), month TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'Monthly', accomplishments TEXT NOT NULL, strengths TEXT DEFAULT '', challenges TEXT DEFAULT '', weaknesses TEXT DEFAULT '', skills_improved TEXT DEFAULT '', support TEXT DEFAULT '', workload INTEGER NOT NULL DEFAULT 3, clarity INTEGER NOT NULL DEFAULT 3, suggestions TEXT DEFAULT '', feedback TEXT DEFAULT '', status TEXT DEFAULT 'Submitted', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE courses(id INTEGER PRIMARY KEY, title TEXT NOT NULL, skill TEXT NOT NULL, resource TEXT NOT NULL, duration_hours REAL NOT NULL DEFAULT 1, cost_cents INTEGER NOT NULL DEFAULT 0);
CREATE TABLE learning_plans(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), course_id INTEGER NOT NULL REFERENCES courses(id), objective TEXT NOT NULL, due TEXT NOT NULL, progress INTEGER DEFAULT 0 CHECK(progress BETWEEN 0 AND 100), pre_score REAL DEFAULT 0, post_score REAL DEFAULT 0, application TEXT DEFAULT '', status TEXT DEFAULT 'Assigned');
CREATE TABLE jobs(id INTEGER PRIMARY KEY, title TEXT NOT NULL, department_id INTEGER NOT NULL REFERENCES departments(id), skills TEXT NOT NULL, description TEXT NOT NULL, status TEXT DEFAULT 'Draft', openings INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE candidates(id INTEGER PRIMARY KEY, job_id INTEGER NOT NULL REFERENCES jobs(id), name TEXT NOT NULL, email TEXT NOT NULL, skills TEXT NOT NULL DEFAULT '[]', experience TEXT DEFAULT '', stage TEXT NOT NULL DEFAULT 'New', cv_text TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE interviews(id INTEGER PRIMARY KEY, candidate_id INTEGER NOT NULL REFERENCES candidates(id), interviewer_id INTEGER NOT NULL REFERENCES employees(id), scheduled_at TEXT NOT NULL, stage TEXT DEFAULT 'Technical', notes TEXT DEFAULT '', skill_score REAL DEFAULT 0, communication_score REAL DEFAULT 0, feedback TEXT DEFAULT '', status TEXT DEFAULT 'Scheduled');
CREATE TABLE documents(id INTEGER PRIMARY KEY, employee_id INTEGER REFERENCES employees(id), candidate_id INTEGER REFERENCES candidates(id), name TEXT NOT NULL, category TEXT NOT NULL, storage_key TEXT NOT NULL, mime TEXT NOT NULL, uploaded_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP, CHECK((employee_id IS NOT NULL)+(candidate_id IS NOT NULL)=1));
CREATE TABLE contracts(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), title TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, probation_end TEXT NOT NULL, notice_days INTEGER NOT NULL CHECK(notice_days>=0), status TEXT DEFAULT 'Active');
CREATE TABLE checklists(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), kind TEXT NOT NULL CHECK(kind IN ('Onboarding','Offboarding')), title TEXT NOT NULL, due TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0);
CREATE TABLE employee_history(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), kind TEXT NOT NULL, detail TEXT NOT NULL, actor_id INTEGER REFERENCES users(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE resignations(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), reason TEXT NOT NULL, submitted TEXT NOT NULL, last_day TEXT NOT NULL, notice_days INTEGER NOT NULL, status TEXT DEFAULT 'Submitted', exit_interview TEXT DEFAULT '', settlement TEXT DEFAULT 'Pending');
CREATE TABLE complaints(id INTEGER PRIMARY KEY, case_ref TEXT UNIQUE NOT NULL, secret_hash TEXT NOT NULL, employee_id INTEGER REFERENCES employees(id), anonymous INTEGER NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, detail TEXT NOT NULL, category TEXT DEFAULT 'General', status TEXT DEFAULT 'Open', owner_id INTEGER REFERENCES users(id), due TEXT NOT NULL, resolution TEXT DEFAULT '', CHECK(anonymous=0 OR employee_id IS NULL));
CREATE TABLE case_history(id INTEGER PRIMARY KEY, complaint_id INTEGER NOT NULL REFERENCES complaints(id), message TEXT NOT NULL, author TEXT NOT NULL, created_day TEXT NOT NULL);
CREATE TABLE surveys(id INTEGER PRIMARY KEY, title TEXT NOT NULL, questions TEXT NOT NULL, anonymous INTEGER NOT NULL DEFAULT 1, start TEXT NOT NULL, end TEXT NOT NULL, status TEXT DEFAULT 'Published');
CREATE TABLE survey_responses(id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL REFERENCES surveys(id), department_id INTEGER REFERENCES departments(id), employee_id INTEGER REFERENCES employees(id), answers TEXT NOT NULL, comment TEXT DEFAULT '');
CREATE TABLE survey_receipts(survey_id INTEGER REFERENCES surveys(id), user_id INTEGER REFERENCES users(id), PRIMARY KEY(survey_id,user_id));
CREATE TABLE tasks(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), team_id INTEGER REFERENCES teams(id), title TEXT NOT NULL, due TEXT NOT NULL, priority TEXT DEFAULT 'Medium', complexity INTEGER DEFAULT 3 CHECK(complexity BETWEEN 1 AND 5), estimated_hours REAL NOT NULL CHECK(estimated_hours>=0), actual_hours REAL DEFAULT 0 CHECK(actual_hours>=0), status TEXT DEFAULT 'To do');
CREATE TABLE recognition(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), author_id INTEGER NOT NULL REFERENCES employees(id), title TEXT NOT NULL, badge TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE articles(id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, content TEXT NOT NULL, owner_id INTEGER NOT NULL REFERENCES users(id), status TEXT DEFAULT 'Draft', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE announcements(id INTEGER PRIMARY KEY, title TEXT NOT NULL, content TEXT NOT NULL, kind TEXT DEFAULT 'Announcement', department_id INTEGER REFERENCES departments(id), event_date TEXT, pinned INTEGER DEFAULT 0, status TEXT DEFAULT 'Draft', author_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), title TEXT NOT NULL, detail TEXT NOT NULL, read INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_interactions(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), agent TEXT NOT NULL, mode TEXT NOT NULL, context_hash TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_tasks_employee ON tasks(employee_id);
CREATE INDEX idx_attendance_employee ON attendance(employee_id,day);
CREATE INDEX idx_leave_employee ON leave_requests(employee_id,status);
INSERT INTO schema_versions(version) VALUES(1);
